SELECT E.SiteName, E.Country, SUM(E.ArtifactWeight) AS TotalWeight FROM ExcavationSites E JOIN (
    SELECT SiteName, Country, SUM(ArtifactWeight) AS TotalWeight
    FROM ExcavationSites
    GROUP BY SiteName, Country
    ORDER BY TotalWeight DESC
) T ON E.SiteName = T.SiteName AND E.Country = T.Country GROUP BY E.SiteName, E.Country;
